// Adds (or refreshes) the logo and navigation header on every document in docs/.
// Idempotent: the header lives between marker comments. Run from the repository root:  node brand/apply-doc-branding.cjs
// docs/API.md is generated by docs/gen-api.cjs, which includes the same header.
const fs = require("fs");
const path = require("path");

const docsDir = path.join(__dirname, "..", "docs");
const NAV = [
  ["Home", "../README.md"], ["Handover", "HANDOVER.md"], ["Architecture", "ARCHITECTURE.md"], ["Development", "DEVELOPMENT.md"],
  ["Extending", "EXTENDING.md"], ["Features", "FEATURES.md"], ["Services", "SERVICES.md"], ["API", "API.md"],
  ["Troubleshooting", "TROUBLESHOOTING.md"], ["Operations", "OPERATIONS.md"],
];

const header = () =>
  `<!-- brand:start -->
<p align="center"><a href="../README.md"><img src="../brand/logo.svg" alt="Matinee" height="56"></a></p>

<p align="center">${NAV.map(([label, href]) => `<a href="${href}">${label}</a>`).join(" · ")}</p>

---
<!-- brand:end -->

`;

module.exports = { header };

if (require.main === module) {
  for (const file of fs.readdirSync(docsDir).filter((f) => f.endsWith(".md"))) {
    const p = path.join(docsDir, file);
    let text = fs.readFileSync(p, "utf8").replace(/<!-- brand:start -->[\s\S]*?<!-- brand:end -->\s*/, "");
    fs.writeFileSync(p, header() + text);
  }
  console.log("branded", fs.readdirSync(docsDir).filter((f) => f.endsWith(".md")).length, "documents");
}
